TLM.f("Sancti/12-25m1",{"officium":"In Nativitate Domini in nocte","rule":["Gloria","Credo","Prefatio=Nat","celebranda aut missa prima aut missa secunda aut missa tertia"],"sections":{"Introitus":[{"k":"ref","la":"Ps 2:7"},{"k":"text","la":"Dóminus dixit ad me: Fílius meus es tu, ego hódie génui te."},{"k":"ref","la":"Ps 2:1"},{"k":"text","la":"Quare fremuérunt gentes: et pópuli meditáti sunt inánia?"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dóminus dixit ad me: Fílius meus es tu, ego hódie génui te."}],"Oratio":[{"k":"text","la":"Deus, qui hanc sacratíssimam noctem veri lúminis fecísti illustratióne claréscere: da, quǽsumus; ut, cujus lucis mystéria in terra cognóvimus, ejus quoque gáudiis in cœlo perfruámur:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beati Pauli Apóstoli ad Titum"},{"k":"ref","la":"Tit 2:11-15"},{"k":"text","la":"Caríssime: Appáruit grátia Dei Salvatóris nostri ómnibus homínibus, erúdiens nos, ut, abnegántes impietátem et sæculária desidéria, sóbrie et juste et pie vivámus in hoc sǽculo, exspectántes beátam spem et advéntum glóriæ magni Dei et Salvatóris nostri Jesu Christi: qui dedit semetípsum pro nobis: ut nos redímeret ab omni iniquitáte, et mundáret sibi pópulum acceptábilem, sectatórem bonórum óperum. Hæc lóquere et exhortáre: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 109:3; 109:1"},{"k":"text","la":"Tecum princípium in die virtútis tuæ: in splendóribus Sanctórum, ex útero ante lucíferum génui te."},{"k":"text","la":"Dixit Dóminus Dómino meo: Sede a dextris meis: donec ponam inimícos tuos, scabéllum pedum tuórum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 2:7"},{"k":"text","la":"Dóminus dixit ad me: Fílius meus es tu, ego hódie génui te. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Lucam"},{"k":"ref","la":"Luc 2:1-14"},{"k":"text","la":"In illo témpore: Exiit edíctum a Cæsare Augústo, ut describerétur univérsus orbis. Hæc descríptio prima facta est a præside Sýriæ Cyríno: et ibant omnes ut profiteréntur sínguli in suam civitátem. Ascéndit autem et Joseph a Galilæa de civitáte Názareth, in Judæam in civitátem David, quæ vocatur Béthlehem: eo quod esset de domo et fámilia David, ut profiterétur cum María desponsáta sibi uxóre prægnánte. Factum est autem, cum essent ibi, impléti sunt dies, ut páreret. Et péperit fílium suum primogénitum, et pannis eum invólvit, et reclinávit eum in præsépio: quia non erat eis locus in diversório. Et pastóres erant in regióne eádem vigilántes, et custodiéntes vigílias noctis super gregem suum. Et ecce, Angelus Dómini stetit juxta illos, et cláritas Dei circumfúlsit illos, et timuérunt timóre magno. Et dixit illis Angelus: Nolíte timére: ecce enim, evangelízo vobis gáudium magnum, quod erit omni pópulo: quia natus est vobis hódie Salvátor, qui est Christus Dóminus, in civitáte David. Et hoc vobis signum: Inveniétis infántem pannis involútum, et pósitum in præsépio. Et súbito facta est cum Angelo multitúdo milítiæ cœléstis, laudántium Deum et dicéntium: Glória in altíssimis Deo, et in terra pax hóminibus bonæ voluntátis."}],"Offertorium":[{"k":"ref","la":"Ps 95:11; 95:13"},{"k":"text","la":"Læténtur cœli et exsúltet terra ante fáciem Dómini: quóniam venit."}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, quǽsumus, hodiérnæ festivitátis oblátio: ut, tua gratia largiénte, per hæc sacrosáncta commércia, in illíus inveniámur forma, in quo tecum est nostra substántia:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Ps 109:3"},{"k":"text","la":"In splendóribus Sanctórum, ex útero ante lucíferum génui te."}],"Postcommunio":[{"k":"text","la":"Da nobis, quǽsumus, Dómine, Deus noster: ut, qui Nativitátem Dómini nostri Jesu Christi mystériis nos frequentáre gaudémus; dignis conversatiónibus ad ejus mereámur perveníre consórtium:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"302b661fa14fc4e2":{"t":"Ps 2, 7, Ps 2, 1\n(Ps 2, 7) Gospodin mi reče: Ti si moj Sin, ja te danas rodih. (Ps 2, 1) Zašto se bune narodi? I zašto narodi snuju isprazne osnove?\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 2, 7) Gospodin mi reče: Ti si moj Sin, ja te danas rodih.","kn":"(Ps. 2, 7). Gospodin mi reče; Ti si Sin moj ja Te danas Todih, (Ps. 2, 1). Zašto se uzbuniše neznabošci i narodi ipomisliše tašta? Slava Ocu . . . Gospodin ...","knRef":"Kniewald 1942, str. 56–57 (snimka 29) (OCR)"},"202f26a1cf214078":{"t":"<i>Pomolimo se</i>.\nBože, koji si dao da ova presveta noć zasja sjajem pravog svjetla, daj, molimo, da i u nebu uživamo radosti onoga čije smo otajstveno svjetlo spoznali na zemlji:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Bože, koji si ovu noć rasvijetlio sjajem pravoga svijetla: učini, molimo Te, da spoznavši na zemlji tajne ovoga svijetla, i na nebu uzmognemo uživati njegove radosti, koji s Tobom živi 1 kraljuje ...","knRef":"Kniewald 1942, str. 56–57 (snimka 29) (OCR)"},"b783e9397f6c6cf1":{"t":"Tit 2, 11-15\nČitanje Poslanice bl. Pavla apostola Titu. Predragi: milost Boga našega Spasitelja objavila se svim ljudima učeći nas, da se odrečemo bezbožnosti i svjetovnih želja i da živimo na ovom svijetu trijezno i pravedno i pobožno, očekujući blaženu nadu i slavni dolazak velikoga Boga i našeg Spasitelja Isusa Krista. On je samog sebe dao za nas, da nas otkupi od svakog bezakonja i da očisti za se izabrani narod koji revnuje oko dobrih djela. Ovo govori i potiči u našemu Gospodinu Isusu Kristu!","kn":"Čitanje poslanice bi. Pavla apostola Titu (2, 11-15). Predragi! Milost Boga našega Spasitelja objavila se svim ljudima učeći naš, da se odrečemo bezbožnosti 1 svjetovnih želja, te da živimo na ovomu svijetu trijezno i ipravedno i pobožno, i čekamo blaženu nadu 1 slavni dolazak velikoga Boga i Spasitelja našega Isusa Krista. On sebe dade za nas, da nas otkupi od svakoga bezakonja i da sebi očisti izabrani narod, koji revnuje oko dobrih djela. Ovo govori 1 potiči u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 66–67 (snimka 34) (OCR)"},"801ef59b49e297ec":{"t":"Ps 109, 3, Ps 109, 1\nU tebe je kraljevska vlast na dan tvoje moći u svetom sjaju prije Danice ja te rodih iz svoga krila. Reče Gospodin Gospodinu mojemu: Sjedi o desnu moju, dok ne položim tvoje neprijatelje za podnožje tvojim nogama.\n\nPs 2, 7\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin mi reče: Ti si moj Sin, ja te danas rodih.<i>Aleluja</i>.","kn":"(Ps. 109, 3, 1). U Tebe je vlast na dan Tvoje moći u sjaju svetih, koji Te prate. Iz krila svoga, rodio sam Te prije danice. Reče Gospodin Gospodinu mojemu: sjedi meni s desna, dok položim Tvoje neprijatelje za podnožje no- gama Tvojim.\n\nAleluja, aleluja. (Ps. 2, 7) GOi^odin mi reče; Ti si Sin moj, ja te danas rodih. Aleluja.","knRef":"Kniewald 1942, str. 56–57 (snimka 29) (OCR)"},"7c4b681230c51f4e":{"t":"Lk 2, 1-14\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: izda car August naredbu da se izvrši popis svega svijeta. Ovaj se prvi popis izvršio, kad je Kvirin bio upravitelj Sirije. I svi su išli da se prijave, svaki u svoj grad. Tako pođe i Josip iz grada Nazareta u Galileji u Judeju, u grad Davidov Betlehem, jer je bio iz doma i roda Davidova, da se upiše s Marijom, svojom zaručenom ženom, koja je bila trudna. Kada su bili ondje, dođe joj vrijeme da rodi. I rodi svojega Sina prvorođenca, povi ga u pelenice i položi u jasle, jer nisu našli mjesta u svratištu. – U onom su kraju pastiri noću bdjeli i čuvali svoje stado. I Gospodnji anđeo stane do njih i obasja ih Božja svjetlost, a oni se vrlo prestraše. Anđeo im reče: »Ne bojte se! Evo, javljam vam veliku radost koja će biti svemu narodu: Danas vam se u Davidovu gradu rodio Spasitelj, to je Krist Gospodin. I evo vam znaka: Naći ćete Dijete povijeno u pelenice i položeno u jasle.« I najednom se s anđelom nađe mnoštvo nebeske vojske koja je hvalila Boga pjesmom: Slava Bogu na visini, i na zemlji mir ljudima dobre volje.","kn":"t Slijedi sveto Evanđelje po Lnki (2, 1-14). U ono vrijeme iziđe naredba od cara Augusta, da se izvrši popis svega svijeta. Ovaj prvi popis bi izvršen, kad je Kvirin upravljao Sirijom.' I polazili su svi da se jave, svaki u svoj grad. Tako i Josip iz grada Naaareta u Galileji pođe sa svojom zaručenom ženom Marijom, koja je bila trudna, javiti se u Judeju, u Betlehem, grad Davidov, jer je bio iz doma i porodice Davidove. Kad su bili ondje, dođe joj vrijeme, da rodi. I rodi svoga prvorođenca, i povi ga u pelenice i položi u jasle, jer nijesu imali mjesta u gostionici. A bili su u onom kraju pastiri, koji su bdjieli i stražili noću nad svojim stadom. I stade do njih anđeo Gospodnji i obasja ih Božja svjetlost i vrlo se prestrašiše. A anđeo im reče: Nemojte se bojati! Evo, javljam vam veliku radost, koja će biti za sav narod; U Davidovu vam se gradu danas rodio Spasitelj, koji je Krist Gospodin. I eto vam znaka: Naći ćete dijete povijano u pelenice i položeno u jasle. I najednom se s anđelom nađe mnogo nebeske vojske, koja je hvalila Boga riječima: Slava na visini Bogu, 1 na zemlji mir ljudima dobre volje.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"bf856040afbc15c8":{"t":"Ps 95, 11 i 13\nNeka se raduje nebo i neka kliče zemlja pred licem Gospodnjim, jer je došao.","kn":"(Ps. 95, 11-13). Neka se vesele nebesa i raduje zemlja pred licem Gospodnjim, jer je došao.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"d8a4c9342d4b80e6":{"t":"Neka ti bude prijatan. Gospodine, žrtveni dar današnje svetkovine, da tvojom milošću po ovoj svetoj izmjeni dobara postanemo slični onome u kojem je s tobom naša narav sjedinjena:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka Ti bude prijatan. Gospodine, žrtveni dar današnje svetkovine 1 podaj,, da se Tvojom izdašnom milošću po ovom presvetom zajedništvu uzvisimo do Onoga, u kome je naša narav s Tobom sjedinjena, koji s Tobom živi i kraljuje , . ,","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"390913ffbc491877":{"t":"Ps 109, 3\nU svetom sjaju prije Danice ja te rodih iz svoga krila.","kn":"(Ps. 109, 3). U sjaju svetih, iz krila svoga rodio sam Te prije danice.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"69a2df052111e198":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine Bože naš, da mi, koji ovim tajnama radosno slavimo rođenje Gospodina našega Isusa Krista, dostojnim vladanjem zaslužimo posve se pridružiti njemu:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj nam, molimo Te, Gospodine, da radosno svetkujemo spomen rođenja Tvoga jedinorođenoga Šina, koji nas hrani ovim nebeskim otajstvom, po istom G. n. I. K.","knRef":"Kniewald 1942, str. 56–57 (snimka 29) (OCR)"}}});
